import { Component } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Pet } from 'src/app/Modele/Pet.model';
import { PetsService } from 'src/app/services/pets.service';

@Component({
  selector: 'app-bird-list',
  templateUrl: './bird-list.component.html',
  styleUrls: ['./bird-list.component.css']
})
export class BirdListComponent {

  pet:Pet[]=[];
  factsVisibility: boolean[] = [];
  newCommentText: string = '';



  constructor(private petsService: PetsService ,
    private route: ActivatedRoute ,
    private petsServie:PetsService

    ) {}

  ngOnInit(): void {



    const type = 'bird'; 

    this.petsService.getPetByType(type).subscribe((pets) => {
      this.pet = pets;
    });
  }

  onDelete(name: string) {
    this.petsServie.deletePet(name).subscribe(
      (response) => {
        console.log('Pet deleted successfully:', response);

        this.loadFishes();
      },
      (error) => {
        console.error('Error deleting pet:', error);
      }
    );
  }

  onLike(petId:number){

  }

  private loadFishes(){
    this.petsServie.getAllPets().subscribe(
      (data) => {
        this.pet = data;
      },
      (error) => {
        console.error('Error loading Fishes:', error);
      }
    );
  }

  changevalue(index: number) {
    this.factsVisibility[index] = !this.factsVisibility[index]; // عكس الحالة للكرت المحدد
  }

}





<div class="conatiner">
  <h2 class="" style="margin-bottom: 20px;"> 𓅰 𓅬 𓅭 BIRD  𓅮 𓅯 𓅰</h2>
  <div class="row">
    <div class=" d-flex flex-wrap ">
      <div *ngFor="let bird of pet;let i = index" class="col-sm-4 mb-4  " >
        <div class="card" style="width: 400px">
          <img [src]="bird.img_url" class="card-img-top mt-1 px-1 borderd" alt="{{ bird.name }} Image" style="height: 200px; object-fit: cover;">

          <div class="card-body">
            <h5 class="card-title">{{ bird.name }}</h5>
            <div *ngIf="factsVisibility[i]">
            <p class="card-text">Type: {{ bird.petType }}</p>

             <ng-container *ngIf="bird.fact">
              <label><h3>Fact:</h3></label>
              <p *ngFor="let sentence of bird.fact.split('.'); let i = index">
                {{ sentence }}{{ i < bird.fact.split('.').length - 1 ? '.' : '' }}
              </p>
              </ng-container>

               <div class="form-group">
                  <textarea
                    class="form-control"
                    id="comment"
                    [(ngModel)]="newCommentText"
                    placeholder="Type your comment here...">
                  </textarea>
                </div>
                <br>
                <div class="heart-btn">
                  <input class="checkbox" type="checkbox"/>
                  <button class="style-btn mb-2"><span>Like</span></button>

                </div>
              </div>
              <button class="btn btn-dark mt-2" (click)="changevalue(i)">
                {{ factsVisibility[i] ? 'Hide' : 'Show Fact' }}
              </button>

                <br>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>


